17	/**
18	 * Custom hook to fetch and manage workspaces data.
19	 * Uses React Query for efficient data fetching and caching.
20	 */
21	export const useWorkspaces = (enabled: boolean) => {
22	  // Fetch workspaces using React Query
23	  const { data, isLoading, isError, refetch } = useQuery<WorkspacesResponse, Error>({
24	    queryKey: ['workspaces'],
25	    queryFn: async () => {
26	      // Don't send X-MLFLOW-WORKSPACE header when listing workspaces
27	      // Otherwise we get stuck when current workspace is filtered out
28	      return fetchAPI(getAjaxUrl(WORKSPACES_ENDPOINT), {
29	        method: HTTPMethods.GET,
30	        headers: {
31	          'X-MLFLOW-WORKSPACE': '',
32	        },
33	      });
34	    },
35	    enabled,
36	    refetchOnWindowFocus: false,
37	    retry: false,
38	  });
39	
40	  // Transform and filter workspaces data
41	  const workspaces = useMemo(() => {
42	    const fetched = Array.isArray(data?.workspaces) ? data.workspaces : [];
43	    const filteredWorkspaces: Workspace[] = [];
44	    for (const item of fetched as Array<Workspace | Record<string, unknown>>) {
45	      if (item && typeof (item as Workspace)?.name === 'string') {
46	        const workspaceItem = item as Workspace;
47	        filteredWorkspaces.push({
48	          name: workspaceItem.name,
49	          description: workspaceItem.description ?? null,
50	          default_artifact_root: workspaceItem.default_artifact_root ?? null,
51	        });
52	      }
53	    }
54	    return filteredWorkspaces;
55	  }, [data]);
56	
57	  return {
58	    workspaces,
59	    isLoading,
60	    isError,
61	    refetch,
62	  } as const;
63	};
64	
